  function renderAdminLogin(errorMsg){
    root.classList.add('hr-auth');
    adminView.innerHTML = authShell('admin', errorMsg);
    wireAuthShell();
    const doLogin = async ()=>{
      const u = document.getElementById('adminUserInput').value.trim();
      const p = document.getElementById('adminPwInput').value.trim();
      if(!u || !p){ renderAdminLogin('Enter your username and password.'); return; }
      const btn = document.getElementById('adminLoginBtn');
      if(btn){ btn.disabled = true; btn.textContent = 'Signing in…'; }
      const res = await env.auth.adminSignIn(u, p);
      if(res && res.error){ renderAdminLogin(res.error); }
      // on success the app loads live data and calls applySession()
    };
    document.getElementById('adminLoginBtn').onclick = doLogin;
    document.getElementById('adminPwInput').addEventListener('keydown', e=>{ if(e.key==='Enter') doLogin(); });
  }

  let adminUnitFilter = 'ALL';
  const UNIT_SCOPED_TABS = new Set(['overview','staff','ledger','planner','tasks','leave','salary','reports']);
  function unitName(code){ const u = UNITS.find(x=>x.code===code); return u ? u.name : code; }
  function deptName(code){ const d = DEPARTMENTS.find(x=>x.code===code); return d ? d.name : code; }
  function desgName(code){ const d = DESIGNATIONS.find(x=>x.code===code); return d ? d.name : code; }
  function nextMasterCode(list, prefix){
    let n = 1;
    const codes = new Set(list.map(x=>x.code));
    while(codes.has(prefix+n)) n++;
    return prefix+n;
  }
  function nextUnitCode(){ return nextMasterCode(UNITS, 'U'); }
  function nextStaffRef(){ return nextMasterCode(STAFF.concat(env.data.SUSPENDED_STAFF||[]).map(s=>({code:s.dbRef})), 'STF'); }
  /* active master items for new choices — a suspended item stays visible only where it is already selected */
  function activeOnly(list, keep){ return list.filter(x=>!x.suspended || (keep!==undefined && x.code===keep)); }
  function suspendBtn(attr, id, suspended){
    return '<button class="iconbtn'+(suspended?'':' danger')+'" '+attr+'="'+id+'">'+(suspended?'Reactivate':'Suspend')+'</button>';
  }
  function suspendedTag(x){ return x && x.suspended ? ' <span class="badge slate" style="padding:1px 6px;font-size:10px;">Suspended</span>' : ''; }
  function inSelectedUnit(empNo){
    if(adminUnitFilter==='ALL') return true;
    const s = findStaff(empNo);
    return s && s.unitCode===adminUnitFilter;
  }
  function unitFilterStaff(list){
    return adminUnitFilter==='ALL' ? list : list.filter(s=>s.unitCode===adminUnitFilter);
  }

  function renderAdmin(){
    if(!adminLoggedIn || !currentAdminAccount){ renderAdminLogin(); return; }
    root.classList.remove('hr-auth');
    const role = currentAdminAccount.role;
    const tabs = ADMIN_TABS_BY_ROLE[role];
    if(!tabs.includes(adminTab)) adminTab = tabs[0];
    const labels = {overview:'Overview', staff:'Staff Master', masters:'Masters', shiftmaster:'Shift Master', ledger:'Shift Ledger', planner:'Shift Planner', tasks:'Tasks', leave:'Leave & Permission', salary:'Salary', reports:'Reports'};
    adminView.innerHTML = ''+
    '<div style="display:flex;justify-content:flex-end;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:10px;">'+
        '<span class="hint mono" style="margin-right:auto;">'+currentAdminAccount.name+' &middot; '+(role==='admin'?'Administrator':'Manager')+'</span>'+
        (UNIT_SCOPED_TABS.has(adminTab) ? '<select class="search" id="adminUnitSel" style="min-width:170px;">'+
          '<option value="ALL" '+(adminUnitFilter==='ALL'?'selected':'')+'>All units</option>'+
          UNITS.map(u=>'<option value="'+u.code+'" '+(adminUnitFilter===u.code?'selected':'')+'>'+u.name+'</option>').join('')+
        '</select>' : '')+
        '<button class="iconbtn" id="adminChangePwBtn">Change password</button>'+
        '<button class="iconbtn" id="adminLogoutBtn">Sign out</button>'+
    '</div>'+
    '<div class="tabs">'+ tabs.map(t=>'<button data-tab="'+t+'" class="'+(adminTab===t?'active':'')+'">'+labels[t]+'</button>').join('') +'</div>'+
    '<div id="adminBody"></div>';
    adminView.querySelectorAll('.tabs button').forEach(b=> b.onclick = ()=>{ adminTab=b.dataset.tab; renderAdmin(); });
    document.getElementById('adminLogoutBtn').onclick = ()=>{ env.auth.signOut(); };
    document.getElementById('adminChangePwBtn').onclick = ()=> openChangePasswordModal('admin');
    const unitSel = document.getElementById('adminUnitSel');
    if(unitSel) unitSel.onchange = (e)=>{ adminUnitFilter = e.target.value; renderAdmin(); };
    if(adminTab==='overview' && role==='manager'){ renderManagerOverview(); return; }
    ({overview:renderAdminOverview, staff:renderAdminStaff, masters:renderAdminMasters, shiftmaster:renderShiftMaster, ledger:renderAdminLedger, planner:renderShiftPlanner, tasks:renderAdminTasks, leave:renderAdminLeave, salary:renderAdminSalary, reports:renderAdminReports})[adminTab]();
  }

  /* ---- Masters: Department / Designation / Unit ---- */
  let mastersSubTab = 'department';
  function renderAdminMasters(){
    const body = document.getElementById('adminBody');
    const subtabs = ['department','designation','unit','holidays','payroll'];
    const subLabels = {department:'Department Master', designation:'Designation Master', unit:'Unit Master', holidays:'Holiday Calendar', payroll:'Payroll Settings'};
    body.innerHTML = ''+
      '<div class="tabs">'+ subtabs.map(t=>'<button data-subtab="'+t+'" class="'+(mastersSubTab===t?'active':'')+'">'+subLabels[t]+'</button>').join('') +'</div>'+
      '<div id="mastersBody"></div>';
    body.querySelectorAll('[data-subtab]').forEach(b=> b.onclick = ()=>{ mastersSubTab=b.dataset.subtab; renderAdminMasters(); });
    ({department:renderDepartmentMaster, designation:renderDesignationMaster, unit:renderUnitMaster, holidays:renderHolidayMaster, payroll:renderPayrollSettings})[mastersSubTab]();
  }

  function renderHolidayMaster(){
    const body = document.getElementById('mastersBody');
    HOLIDAYS.sort((a,b)=>a.date.localeCompare(b.date));
    body.innerHTML = ''+
    '<div class="emp-toolbar"><div class="section-title" style="margin:0;">Holiday calendar</div><button class="btn" id="addHolidayBtn">+ Add holiday</button></div>'+
    '<div class="tbl-scroll"><table class="narrow"><thead><tr><th>Date</th><th>Name</th><th>Status</th><th></th></tr></thead><tbody>'+
    (HOLIDAYS.map((h,i)=>(
      '<tr>'+
        '<td class="mono">'+fmtDate(h.date)+'</td>'+
        '<td><input class="editable" data-idx="'+i+'" data-field="name" value="'+escapeAttr(h.name)+'"></td>'+
        '<td>'+(h.suspended?'<span class="badge slate">Suspended</span>':'<span class="badge teal">Active</span>')+'</td>'+
        '<td>'+suspendBtn('data-susp-hol', i, h.suspended)+'</td>'+
      '</tr>'
    )).join('') || '<tr><td colspan="3" class="note">No holidays declared yet.</td></tr>')+
    '</tbody></table></div>'+
    '<div class="footnote">A declared holiday overrides whatever the biometric device recorded for that date — no lateness, absence or deduction is calculated for it, for any staff member, on any shift.</div>';
    document.getElementById('addHolidayBtn').onclick = ()=>{
      openMasterAddModal('Add holiday', [
        {id:'date', label:'Date', type:'date', value:todayISO()},
        {id:'name', label:'Holiday name', placeholder:'e.g. Diwali'},
      ], (v)=>{
        const ex = HOLIDAYS.find(h=>h.date===v.date);
        if(ex){ ex.name = v.name; ex.suspended = false; } else HOLIDAYS.push({date:v.date, name:v.name});
        renderAdminMasters();
      });
    };
    body.querySelectorAll('.editable').forEach(inp=>{
      inp.addEventListener('change', ()=>{ HOLIDAYS[parseInt(inp.dataset.idx)].name = inp.value; renderAdminMasters(); });
    });
    body.querySelectorAll('[data-susp-hol]').forEach(btn=>{
      btn.onclick = ()=>{ const h = HOLIDAYS[parseInt(btn.dataset.suspHol)]; h.suspended = !h.suspended; renderAdminMasters(); };
    });
  }

