    '</div>'+

    '<div class="section-title">Professional Tax slabs</div>'+
    '<div class="tbl-scroll"><table class="narrow"><thead><tr><th>Gross salary up to (₹)</th><th>PT (₹/month)</th><th></th></tr></thead><tbody>'+
    p.pt.slabs.map((s,i)=>(
      '<tr>'+
        '<td><input class="editable mono" data-pt-idx="'+i+'" data-pt-field="upto" type="number" value="'+s.upto+'"></td>'+
        '<td><input class="editable mono" data-pt-idx="'+i+'" data-pt-field="amount" type="number" value="'+s.amount+'"></td>'+
        '<td><button class="iconbtn danger" data-del-pt="'+i+'">Remove</button></td>'+
      '</tr>'
    )).join('')+
    '</tbody></table></div>'+
    '<div class="form-row"><label><input type="checkbox" id="psPtOn" '+(p.pt.enabled?'checked':'')+'> Professional Tax enabled</label></div>'+
    '<button class="iconbtn" id="addPtSlabBtn" style="margin-bottom:12px;">+ Add slab</button>'+

    '<div class="section-title">Overtime</div>'+
    '<div class="form-grid">'+
      '<div class="form-row"><label><input type="checkbox" id="psOtOn" '+(p.ot.enabled?'checked':'')+'> Enabled</label></div>'+
      '<div class="form-row"><label>Multiplier (&times; hourly rate)</label><input id="psOtMult" type="number" min="1" step="0.1" value="'+p.ot.multiplier+'"></div>'+
      '<div class="form-row"><label>Grace before OT starts (min)</label><input id="psOtGrace" type="number" min="0" value="'+p.ot.graceMin+'"></div>'+
    '</div>'+

    '<button class="btn" style="width:100%;margin-top:8px;" id="psSave">Save payroll settings</button>'+
    '<div class="footnote">These PF/ESI/Professional Tax rates and slabs are editable defaults for this demo, not authoritative figures — confirm the actual applicable rates with your accountant before relying on them for real payroll. Overtime pay is calculated from actual out-time minus the shift\'s end time (overnight shifts aren\'t modeled yet) for staff marked OT-eligible in Staff Master → Details.</div>';

    document.getElementById('addPtSlabBtn').onclick = ()=>{ p.pt.slabs.push({upto:0, amount:0}); renderAdminMasters(); };
    body.querySelectorAll('[data-del-pt]').forEach(btn=> btn.onclick = ()=>{ p.pt.slabs.splice(parseInt(btn.dataset.delPt),1); renderAdminMasters(); });
