    simpleListMaster({
      list: DESIGNATIONS, itemLabel:'Designation', prefix:'DSG',
      usedCountFn: (v)=> STAFF.filter(s=>s.designation===v.code).length,
      onAdd: (name)=>{ DESIGNATIONS.push({code: nextMasterCode(DESIGNATIONS,'DSG'), name}); renderAdminMasters(); },
      onRename: (i, name)=>{ DESIGNATIONS[i].name = name; renderAdminMasters(); },
      onRemove: (i)=>{ DESIGNATIONS.splice(i,1); renderAdminMasters(); },
    });
