  /* ---- Shift Master ---- */
  function renderShiftMaster(){
    const body = document.getElementById('adminBody');
    body.innerHTML = ''+
    '<div class="emp-toolbar"><div class="section-title" style="margin:0;">Shift types</div><button class="btn" id="addShiftBtn">+ Add shift type</button></div>'+
    '<div class="tbl-scroll"><table class="narrow"><thead><tr>'+
      '<th>Code</th><th>Shift name</th><th>Badge</th><th>Start time</th><th>End time</th><th>Allowed late (min)</th><th>Allowed extra-late (min)</th><th>Times / salary month</th><th></th>'+
    '</tr></thead><tbody>'+
    SHIFT_MASTER.map(s=>(
      '<tr data-code="'+s.code+'">'+
        '<td class="mono">'+s.code+'</td>'+
        '<td><input class="editable" data-field="name" value="'+escapeAttr(s.name)+'"></td>'+
        '<td><input class="editable mono" data-field="letter" value="'+escapeAttr(s.letter)+'" maxlength="2" style="width:44px;"></td>'+
        '<td><input class="editable mono" data-field="start" type="time" value="'+s.start+'"></td>'+
        '<td><input class="editable mono" data-field="end" type="time" value="'+s.end+'"></td>'+
        '<td><input class="editable mono" data-field="allowedLateMin" type="number" min="0" value="'+s.allowedLateMin+'" style="width:64px;"></td>'+
        '<td><input class="editable mono" data-field="allowedExtraLateMin" type="number" min="0" value="'+s.allowedExtraLateMin+'" style="width:64px;"></td>'+
        '<td><input class="editable mono" data-field="extraLateMaxPerMonth" type="number" min="0" value="'+s.extraLateMaxPerMonth+'" style="width:56px;"></td>'+
        '<td>'+suspendBtn('data-susp-shift', s.code, s.suspended)+suspendedTag(s)+'</td>'+
      '</tr>'
    )).join('')+
    '</tbody></table></div>'+
    '<div class="footnote">Allowed late = always-forgiven grace for that shift. Allowed extra-late = a further band forgiven only a limited number of times per salary month (once used up, or once late exceeds grace + extra-late, the full late duration is charged against the permission pool and then pay, exactly as on the Shift Ledger). Map each staff member to a shift on Staff Master — the Shift Planner can still override any individual date.</div>';

    document.getElementById('addShiftBtn').onclick = ()=>{
      const nextCode = nextMasterCode(SHIFT_MASTER, 'S');
      openMasterAddModal('Add shift type', [
        {id:'name', label:'Shift name', placeholder:'e.g. Morning Shift'},
        {id:'letter', label:'Badge (1-2 letters)', placeholder:'e.g. M'},
        {id:'start', label:'Start time', type:'time', value:'09:00'},
        {id:'end', label:'End time', type:'time', value:'18:00'},
        {id:'allowedLateMin', label:'Allowed late (min)', type:'number', value:15},
        {id:'allowedExtraLateMin', label:'Allowed extra time (min)', type:'number', value:15},
        {id:'extraLateMaxPerMonth', label:'Times / salary month', type:'number', value:3},
      ], (v)=>{
        SHIFT_MASTER.push({
          code: nextCode, name:v.name, letter:v.letter.toUpperCase().slice(0,2),
          start:v.start, end:v.end,
          allowedLateMin: parseInt(v.allowedLateMin)||0,
          allowedExtraLateMin: parseInt(v.allowedExtraLateMin)||0,
          extraLateMaxPerMonth: parseInt(v.extraLateMaxPerMonth)||0,
        });
        renderShiftMaster();
      }, 'Code to be assigned: <span class="mono">'+nextCode+'</span> (permanent, auto-generated).');
    };
    body.querySelectorAll('.editable').forEach(inp=>{
      inp.addEventListener('change', ()=>{
        const code = inp.closest('tr').dataset.code;
        const s = shiftByCode(code);
        const field = inp.dataset.field;
        const numeric = ['allowedLateMin','allowedExtraLateMin','extraLateMaxPerMonth'].includes(field);
        s[field] = numeric ? (parseInt(inp.value)||0) : inp.value;
      });
    });
    body.querySelectorAll('[data-susp-shift]').forEach(btn=>{
      btn.onclick = ()=>{
        const s = shiftByCode(btn.dataset.suspShift);
        if(!s) return;
        if(!s.suspended && activeOnly(SHIFT_MASTER).length<=1){ alert('Keep at least one active shift type.'); return; }
        s.suspended = !s.suspended;
        renderShiftMaster();
      };
    });
  }

  /* ---- Shift Planner ---- */
  let plannerMonth = null;
  let plannerQuery = '';
  function allCycleDates(){
    const s = new Set();
    Object.values(ATTENDANCE).forEach(a=> a.records.forEach(r=> s.add(r.date)));
    return [...s].filter(d=> d>=env.cycle.start && d<=env.cycle.end).sort();
  }
  function monthsAvailable(){
    return [...new Set(allCycleDates().map(d=>d.slice(0,7)))].sort();
  }
  function monthLabel(ym){
    const [y,m] = ym.split('-').map(Number);
    return new Date(y, m-1, 1).toLocaleDateString('en-IN', {month:'long', year:'numeric'});
  }
  function renderShiftPlanner(){
    const body = document.getElementById('adminBody');
    const months = monthsAvailable();
    if(!plannerMonth) plannerMonth = months[0];
    const datesInMonth = allCycleDates().filter(d=> d.startsWith(plannerMonth));
    const filteredStaff = unitFilterStaff(STAFF).filter(e=> (e.name+e.empNo+deptName(e.department)).toLowerCase().includes(plannerQuery.toLowerCase()));

    const head = '<th class="mono">Code</th><th>Name</th>'+datesInMonth.map(d=>{
      const day = new Date(d+'T00:00:00');
      const isSun = day.getDay()===0;
      return '<th class="mono"'+(isSun?' style="color:var(--rose);"':'')+' title="'+d+'">'+day.getDate()+'</th>';
    }).join('');

    const rows = filteredStaff.map(s=>{
      const att = ATTENDANCE[s.empNo];
      const byDate = {}; att.records.forEach(r=> byDate[r.date]=r);
      const cells = datesInMonth.map(d=>{
        const rec = byDate[d];
        if(!rec || rec.status!=='P'){
          const label = rec ? ({WO:'WO',A:'A',CL:'CL'})[rec.status]||rec.status : '';
          return '<td class="mono" style="text-align:center;color:var(--slate-soft);font-size:11px;">'+label+'</td>';
        }
        const inMin = toMin(rec.in);
        const sh = effectiveShift(s.empNo, d, inMin);
        const overridden = isOverridden(s.empNo, d);
        const late = Math.max(0, inMin - shiftStartMin(sh));
        const grace = sh.allowedLateMin ?? 15;
        const cls = {S1:'planner-g', S2:'planner-s', S3:'planner-n'}[sh.code] || 'planner-x';
        return '<td style="text-align:center;">'+
          '<button class="planner-cell '+cls+(overridden?' planner-override':'')+'" data-emp="'+s.empNo+'" data-date="'+d+'" title="'+sh.name+(late>grace?' — '+late+'m late':'')+'">'+
            sh.letter+(late>grace?'<span class="planner-late-dot"></span>':'')+
          '</button>'+
        '</td>';
      }).join('');
      return '<tr><td class="mono">'+s.empNo+'</td><td>'+s.name+'</td>'+cells+'</tr>';
    }).join('');

    body.innerHTML = ''+
    '<div class="emp-toolbar">'+
      '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">'+
        '<select class="search" id="plannerMonthSel" style="min-width:160px;">'+months.map(m=>'<option value="'+m+'" '+(m===plannerMonth?'selected':'')+'>'+monthLabel(m)+'</option>').join('')+'</select>'+
        '<input class="search" id="plannerSearch" placeholder="Search staff..." value="'+escapeAttr(plannerQuery)+'" />'+
      '</div>'+
      '<div style="display:flex;gap:6px;align-items:center;font-size:11.5px;color:var(--slate);">'+
        '<span class="planner-cell planner-g" style="pointer-events:none;">G</span> General &nbsp;'+
        '<span class="planner-cell planner-s" style="pointer-events:none;">S</span> Second &nbsp;'+
        '<span class="planner-cell planner-n" style="pointer-events:none;">N</span> Night'+
      '</div>'+
    '</div>'+
    '<div class="tbl-scroll"><table class="narrow"><thead><tr>'+head+'</tr></thead><tbody>'+rows+'</tbody></table></div>'+
    '<div class="footnote">Click any shift badge to change that staff member\'s shift for that exact date — past, current or future, any time before the cycle\'s salary is finalized. A gold ring marks a manual override; a red dot marks a day that\'s late against whichever shift is in effect. Changes apply immediately to Shift Ledger, Salary and the staff member\'s own dashboard.</div>';

    document.getElementById('plannerMonthSel').onchange = (e)=>{ plannerMonth = e.target.value; renderShiftPlanner(); };
    document.getElementById('plannerSearch').oninput = (e)=>{ plannerQuery = e.target.value; renderShiftPlanner(); };
    body.querySelectorAll('.planner-cell[data-emp]').forEach(btn=>{
      btn.onclick = ()=>{
        if(env.data.PAYROLL.run){ alert('This pay cycle is finalized. Reopen it on the Salary tab to change shifts.'); return; }
        const emp = btn.dataset.emp, date = btn.dataset.date;
        const rec = ATTENDANCE[emp].records.find(r=>r.date===date);
        const current = effectiveShift(emp, date, toMin(rec.in)).code;
        ROSTER[rosterKey(emp, date)] = nextShiftCode(current);
        renderShiftPlanner();
      };
    });
  }

  /* ---- lightweight themed CSS visuals (no external chart lib) ---- */
  function dailyAttendanceSeries(scopedIds){
    const anyAtt = {records: allCycleDates().map(d=>({date:d}))};
    if(!anyAtt.records.length) return [];
    return anyAtt.records.map(r0=>{
      let present=0, total=0;
      scopedIds.forEach(id=>{
        const att = ATTENDANCE[id]; if(!att) return;
        const rec = att.records.find(r=>r.date===r0.date); if(!rec) return;
        if(rec.status==='WO' || rec.status==='H') return;
        total++; if(rec.status==='P') present++;
      });
      return {date:r0.date, pct: total? Math.round(present/total*100) : null};
    });
  }
  function miniBarChart(series, opts){
    opts = opts||{};
    const vals = series.map(s=>s.value).filter(v=>v!=null);
    const max = opts.max || Math.max(...vals, 1);
    return '<div style="display:flex;align-items:flex-end;gap:3px;height:90px;padding:10px 8px;border:1px solid var(--line);border-radius:10px;background:var(--surface);overflow-x:auto;">'+
      series.map(s=>{
        const h = s.value==null ? 3 : Math.max(4, Math.round((s.value/max)*76));
        return '<div title="'+escapeAttr(s.label+': '+(s.value==null?'no data':s.value+(opts.suffix||'')))+'" style="flex:0 0 auto;width:'+(opts.barWidth||8)+'px;height:'+h+'px;background:'+(s.value==null?'var(--line)':(opts.color||'var(--teal)'))+';border-radius:2px 2px 0 0;"></div>';
      }).join('')+
    '</div>';
  }
  function topList(items, opts){
    opts = opts||{};
    if(!items.length) return '<div class="note" style="padding:10px 0;">No data.</div>';
    const max = Math.max(...items.map(i=>i.value),1);
    return '<div style="display:flex;flex-direction:column;gap:7px;">'+
      items.map(i=>'<div style="display:flex;align-items:center;gap:8px;">'+
        '<div style="min-width:130px;max-width:240px;font-size:12px;color:var(--slate);">'+i.label+'</div>'+
        '<div style="flex:1;background:var(--line);border-radius:5px;height:10px;overflow:hidden;"><div style="width:'+Math.max(4,Math.round(i.value/max*100))+'%;height:100%;background:'+(opts.color||'var(--rose)')+';"></div></div>'+
        '<div class="mono" style="width:'+(opts.valueWidth||'30px')+';text-align:right;font-size:12px;">'+i.value+'</div>'+
      '</div>').join('')+
    '</div>';
  }
  function stackedBar(segments){
    const total = segments.reduce((s,x)=>s+x.value,0) || 1;
    return '<div style="display:flex;height:22px;border-radius:6px;overflow:hidden;background:var(--line);">'+
      segments.map(s=> s.value>0 ? '<div title="'+escapeAttr(s.label+': '+fmtMoney(s.value))+'" style="width:'+(s.value/total*100)+'%;background:'+s.color+';"></div>' : '').join('')+
    '</div>'+
    '<div style="display:flex;gap:14px;flex-wrap:wrap;margin-top:8px;">'+
      segments.map(s=>'<span style="font-size:11.5px;color:var(--slate);display:flex;align-items:center;gap:5px;"><span style="width:9px;height:9px;border-radius:2px;background:'+s.color+';display:inline-block;"></span>'+s.label+': '+fmtMoney(s.value)+'</span>').join('')+
    '</div>';
  }

