  /* ================= Attendance import ================= */
  function parseCSVLine(line){
    const cells = []; let cur=''; let inQ=false;
    for(let i=0;i<line.length;i++){
      const c = line[i];
      if(inQ){
        if(c==='"'){ if(line[i+1]==='"'){ cur+='"'; i++; } else { inQ=false; } }
        else cur+=c;
      } else {
        if(c==='"') inQ=true;
        else if(c===','){ cells.push(cur); cur=''; }
        else cur+=c;
      }
    }
    cells.push(cur);
    return cells;
  }
  const ATT_IMPORT_MONTHS = {Jan:'01',Feb:'02',Mar:'03',Apr:'04',May:'05',Jun:'06',Jul:'07',Aug:'08',Sep:'09',Oct:'10',Nov:'11',Dec:'12'};
  function parseDMonY(s){
    const m = /^(\d{1,2})-([A-Za-z]{3})-(\d{4})$/.exec((s||'').trim());
    if(!m) return null;
    const key = m[2][0].toUpperCase()+m[2].slice(1,3).toLowerCase();
    const mo = ATT_IMPORT_MONTHS[key];
    if(!mo) return null;
    return m[3]+'-'+mo+'-'+(m[1].length===1?'0'+m[1]:m[1]);
  }
  function mapAttStatusText(s){
    s = (s||'').trim();
    if(/not\s*present|absent/i.test(s)) return 'A';
    if(/present/i.test(s)) return 'P';
    if(/weekly\s*off|week\s*off/i.test(s)) return 'WO';
    if(/holiday/i.test(s)) return 'H';
    if(/\bcl\b|casual\s*leave|\bleave\b/i.test(s)) return 'CL';
    if(/absent|not\s*present/i.test(s)) return 'A';
    return null;
  }
  function parseAttendanceImportText(text){
    const lines = text.split(/\r?\n/).filter(l=>l.trim().length);
    const head = lines.slice(0,6).join(' ');
    const result = {records:[], unmatchedCodes:new Set(), warnings:[], format:null, names:{}};
    if(!lines.length) return result;
    if(/Employee\s*Punch\s*Monitor/i.test(head)){
      result.format = 'Employee Punch Monitor (single day)';
      let reportDate = null, headerSeen = false;
      for(const line of lines){
        const cells = parseCSVLine(line).map(c=>c.trim());
        if(!reportDate && /^date$/i.test(cells[0]||'')){
          const d = cells.slice(1).find(c=>parseDMonY(c));
          if(d) reportDate = parseDMonY(d);
          continue;
        }
        if(!headerSeen && /^sno/i.test(cells[0]||'')){ headerSeen = true; continue; }
        if(headerSeen){
          const code = cells[1];
          if(!code) continue;
          if(cells[3]) result.names[code] = cells[3];
          const punches = (cells[7]||'').split(',').map(p=>p.trim()).filter(Boolean);
          const status = mapAttStatusText(cells[9]) || (punches.length ? 'P' : 'A');
          if(!reportDate){ result.warnings.push('No report date found in the Punch Monitor header.'); continue; }
          const rec = {empNo: code, date: reportDate, status};
          if(punches.length){ rec.in = punches[0]; rec.out = punches[punches.length-1]; }
          result.records.push(rec);
        }
      }
    } else if(/Daily\s*Attendance\s*Report/i.test(head) || /DailyAttendance_SummaryReport/i.test(head)){
      result.format = 'Daily Attendance Summary Report (per-employee)';
      let curCode = null;
      for(const line of lines){
        const cells = parseCSVLine(line).map(c=>c.trim());
        if(/^Employee\s*Code:?$/i.test(cells[1]||'')){
          curCode = cells[3] || null;
          const ni = cells.findIndex(c=>/^Employee\s*Name/i.test(c));
          const nm = ni>=0 ? cells.slice(ni+1).find(c=>c) : '';
          if(curCode && nm) result.names[curCode] = nm;
          continue;
        }
        if(/^Date$/i.test(cells[1]||'')) continue;
        if(/^Total\s*Duration=/i.test(cells[1]||'')) continue;
        const iso = parseDMonY(cells[1]);
        if(iso && curCode){
          const status = mapAttStatusText(cells[8]) || 'A';
          const rec = {empNo: curCode, date: iso, status};
          if(cells[3]) rec.in = cells[3];
          if(cells[4]) rec.out = cells[4];
          result.records.push(rec);
        }
      }
    } else {
      result.format = 'Generic CSV';
      const header = parseCSVLine(lines[0]).map(c=>c.trim().toLowerCase());
      const idx = (re)=> header.findIndex(h=>re.test(h));
      const cName = idx(/name/);
      const cCode = idx(/emp.*code|^code$/), cDate = idx(/date/), cStatus = idx(/status/), cIn = idx(/in.?time|check.?in|^in$/), cOut = idx(/out.?time|check.?out|^out$/);
      if(cCode<0 || cDate<0){
        result.warnings.push('Could not find header columns for employee code and date.');
      } else {
        for(let i=1;i<lines.length;i++){
          const cells = parseCSVLine(lines[i]).map(c=>c.trim());
          const code = cells[cCode]; if(!code) continue;
          if(cName>=0 && cells[cName]) result.names[code] = cells[cName];
          const dateRaw = cells[cDate];
          let iso = /^\d{4}-\d{2}-\d{2}$/.test(dateRaw) ? dateRaw : parseDMonY(dateRaw);
          if(!iso){ const m=/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/.exec(dateRaw); if(m) iso = m[3]+'-'+m[1].padStart(2,'0')+'-'+m[2].padStart(2,'0'); }
          if(!iso) continue;
          const rawStatus = cStatus>=0 ? cells[cStatus] : '';
          const status = mapAttStatusText(rawStatus) || (rawStatus ? rawStatus.toUpperCase().slice(0,2) : 'P');
          const rec = {empNo: code, date: iso, status};
          if(cIn>=0 && cells[cIn]) rec.in = cells[cIn];
          if(cOut>=0 && cells[cOut]) rec.out = cells[cOut];
          result.records.push(rec);
        }
      }
    }
    const knownCodes = new Set(STAFF.map(s=>s.empNo));
    result.records.forEach(r=>{ if(!knownCodes.has(r.empNo)) result.unmatchedCodes.add(r.empNo); });
    return result;
  }
  function openAttendanceImportModal(){
    const modalRoot = document.getElementById('modalRoot');
    modalRoot.innerHTML = ''+
    '<div class="modal-back" id="modalBack"><div class="modal">'+
      '<div class="modal-head"><h3 style="font-size:15px;">Import attendance</h3><button class="closebtn" id="modalClose">✕</button></div>'+
      '<div class="modal-body">'+
        '<div class="hint" style="margin-bottom:10px;">Recognizes the biometric device\'s <b>Daily Attendance Report (Summary Report)</b> export and <b>Employee Punch Monitor</b> export, saved or copied as CSV/text — plus a plain CSV with Employee Code / Date / Status / In / Out columns.'+
        ' Upload the <b>.xls / .xlsx</b> file straight from the device software, or a CSV / text export, or paste the report below.'+
        '</div>'+
        '<div class="form-row"><label>Upload the device export (.xls / .xlsx / .csv / .txt)</label><input type="file" id="attImportFile" accept=".xls,.xlsx,.csv,.txt,.tsv"></div>'+
        '<div class="form-row"><label>...or paste the report text</label><textarea id="attImportText" rows="8" style="width:100%;font-family:monospace;font-size:12px;" placeholder="Paste CSV/text here"></textarea></div>'+
        '<button class="btn" id="attImportParseBtn">Preview import</button>'+
        '<div id="attImportPreview" style="margin-top:12px;"></div>'+
      '</div>'+
    '</div></div>';
    document.getElementById('modalClose').onclick = ()=> modalRoot.innerHTML='';
    document.getElementById('modalBack').addEventListener('click', e=>{ if(e.target.id==='modalBack') modalRoot.innerHTML=''; });
    document.getElementById('attImportFile').addEventListener('change', (e)=>{
      const f = e.target.files[0]; if(!f) return;
      if(/\.xlsx?$/i.test(f.name)){
        const ta = document.getElementById('attImportText');
        ta.value = 'Reading '+f.name+'…';
        env.excelToCsv(f).then(csv=>{ ta.value = csv; document.getElementById('attImportParseBtn').click(); })
          .catch(err=>{ ta.value = ''; alert('Could not read '+f.name+': '+((err && err.message) || err)); });
        return;
      }
      const reader = new FileReader();
      reader.onload = ()=>{ document.getElementById('attImportText').value = reader.result; };
      reader.readAsText(f);
    });
    document.getElementById('attImportParseBtn').onclick = ()=>{
      const text = document.getElementById('attImportText').value;
      const previewEl = document.getElementById('attImportPreview');
      if(!text.trim()){ previewEl.innerHTML = '<div class="error-text">Paste or upload some data first.</div>'; return; }
      const parsed = parseAttendanceImportText(text);
      renderAttImportPreview(parsed);
    };
  }
  function renderAttImportPreview(parsed){
    const el = document.getElementById('attImportPreview');
    if(!parsed.records.length){
      el.innerHTML = '<div class="error-text">No recognizable attendance rows found. '+(parsed.warnings.join(' ')||'Check the format and try again, or export as CSV instead of .xls.')+'</div>';
      return;
    }
    const matched = parsed.records.filter(r=>!parsed.unmatchedCodes.has(r.empNo));
    const dates = new Set(parsed.records.map(r=>r.date));
    el.innerHTML = ''+
      '<div class="stats">'+
        stat('Detected format', parsed.format)+
        stat('Rows recognized', parsed.records.length)+
        stat('Employees matched', new Set(matched.map(r=>r.empNo)).size)+
        stat('Dates covered', dates.size)+
      '</div>'+
      newStaffPanel(parsed)+
      '<div class="tbl-scroll" style="max-height:220px;"><table><thead><tr><th>Code</th><th>Name</th><th>Date</th><th>Status</th><th>In</th><th>Out</th></tr></thead><tbody>'+
        matched.slice(0,25).map(r=>{
          const s = findStaff(r.empNo);
          return '<tr><td class="mono">'+r.empNo+'</td><td>'+(s?s.name:'—')+'</td><td class="mono">'+r.date+'</td><td>'+r.status+'</td><td class="mono">'+(r.in||'—')+'</td><td class="mono">'+(r.out||'—')+'</td></tr>';
        }).join('')+
      '</tbody></table></div>'+
      (matched.length>25 ? '<div class="hint">Showing first 25 of '+matched.length+' recognized rows.</div>' : '')+
      '<div class="error-text" id="attImportError"></div>'+
      '<button class="btn" style="margin-top:10px;" id="attImportCommitBtn">Import</button>';
    wireNewStaffPanel(parsed);
  }

  /* New staff found in an import: the only question asked is which unit they belong to.
     They are added to Staff Master (Role Staff, password = Staff Code); salary, designation
     and department can be completed later in Staff Master. Existing staff keep their unit —
     transfers are made in Staff Master (Unit column), which records the transfer history. */
  function cleanImportedName(n, code){
    n = String(n||'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,100);
    if(!n || n===code) return '';
    return n.replace(/^(mr|mrs|ms|miss|mst)\.?\s+/i,'').trim().toUpperCase();
  }
  function newStaffPanel(parsed){
    const suspendedCodes = new Set((env.data.SUSPENDED_STAFF||[]).map(s=>s.empNo));
    const codes = Array.from(parsed.unmatchedCodes).filter(c=>!suspendedCodes.has(c));
    const skippedSuspended = Array.from(parsed.unmatchedCodes).filter(c=>suspendedCodes.has(c));
    const note = skippedSuspended.length ? '<div class="footnote">Suspended staff in this file — skipped (reactivate them in Staff Master to include): '+skippedSuspended.join(', ')+'</div>' : '';
    if(!codes.length) return note;
    const act = (list)=> list.filter(x=>!x.suspended);
    const need = [];
    if(!act(UNITS).length) need.push('a Unit');
    if(!act(DEPARTMENTS).length) need.push('a Department');
    if(!act(DESIGNATIONS).length) need.push('a Designation');
    if(!act(SHIFT_MASTER).length) need.push('a Shift type (Shift Master)');
    const head = '<div class="section-title" style="margin-top:14px;">'+(STAFF.length===0?'First import — staff found in this file':'New staff found in this file')+' ('+codes.length+')</div>';
    if(need.length){
      return note+head+'<div class="error-text" style="margin-bottom:8px;">To add these staff, first create at least '+need.join(', ')+' in Masters / Shift Master. Until then only staff already in Staff Master are imported.</div>'+
        '<div class="hint">'+codes.map(c=>c+' '+cleanImportedName(parsed.names[c], c)).join(' · ')+'</div>';
    }
    const opt = (list, lbl)=> '<option value="">'+lbl+'</option>'+act(list).map(x=>'<option value="'+x.code+'">'+x.name+'</option>').join('');
    const mgrOpts = '<option value="">— none —</option>'+STAFF.filter(m=>m.role==='Manager').map(m=>'<option value="'+m.empNo+'">'+m.name+'</option>').join('');
    const allRow = '<tr style="background:var(--surface-2);"><td></td><td class="hint">Apply to all ↓</td><td></td>'+
      '<td><select class="editable ns-all" data-f="unit" style="min-width:150px;">'+opt(UNITS,'—')+'</select></td>'+
      '<td><select class="editable ns-all" data-f="dept" style="min-width:150px;">'+opt(DEPARTMENTS,'—')+'</select></td>'+
      '<td><select class="editable ns-all" data-f="desg" style="min-width:140px;">'+opt(DESIGNATIONS,'—')+'</select></td>'+
      '<td><select class="editable ns-all" data-f="shift" style="min-width:140px;">'+opt(SHIFT_MASTER,'—')+'</select></td>'+
      '<td></td><td><select class="editable ns-all" data-f="mgr" style="min-width:150px;">'+mgrOpts+'</select></td>'+
      '<td></td><td><input class="editable mono ns-all" data-f="doj" type="date"></td>'+
      '<td><input class="editable mono ns-all" data-f="cl" type="number" min="0" step="0.5" style="width:60px;" placeholder="'+DEFAULT_MONTHLY_CL+'"></td>'+
      '<td><input class="editable mono ns-all" data-f="perm" type="number" min="0" step="0.5" style="width:60px;" placeholder="'+(DEFAULT_MONTHLY_PERMISSION_MIN/60)+'"></td></tr>';
    return note+head+
    '<div class="hint" style="margin-bottom:8px;">These codes are not in Staff Master yet. Staff Code and name come from the file; fill in the rest once — it is saved to Staff Master with this import. <b>Unit, Department, Designation, Shift and Gross salary are required.</b> Untick anyone who should not be added (their rows are skipped). Use the first row to fill a column for everyone.</div>'+
    '<div class="tbl-scroll" style="max-height:360px;"><table><thead><tr><th>Add</th><th>Staff Code</th><th>Name</th><th>Unit *</th><th>Department *</th><th>Designation *</th><th>Shift *</th><th>Role</th><th>Reporting Manager</th><th>Gross salary ₹ *</th><th>Date of joining</th><th>CL / month</th><th>Perm. hrs / month</th></tr></thead><tbody>'+
    allRow+
    codes.map(code=>{
      const nm = cleanImportedName(parsed.names[code], code);
      return '<tr class="ns-row" data-code="'+escapeAttr(code)+'">'+
        '<td><input type="checkbox" class="ns-inc" checked></td>'+
        '<td class="mono">'+code+'</td>'+
        '<td>'+(nm ? '<span class="ns-name-fixed">'+escapeHTML(nm)+'</span><input type="hidden" class="ns-name" value="'+escapeAttr(nm)+'">'
                   : '<input class="editable ns-name" maxlength="100" style="min-width:170px;" placeholder="Name not in file — type it">')+'</td>'+
        '<td><select class="editable ns-unit" style="min-width:150px;">'+opt(UNITS,'Select…')+'</select></td>'+
        '<td><select class="editable ns-dept" style="min-width:150px;">'+opt(DEPARTMENTS,'Select…')+'</select></td>'+
        '<td><select class="editable ns-desg" style="min-width:140px;">'+opt(DESIGNATIONS,'Select…')+'</select></td>'+
        '<td><select class="editable ns-shift" style="min-width:140px;">'+opt(SHIFT_MASTER,'Select…')+'</select></td>'+
        '<td><select class="editable ns-role" style="min-width:120px;"><option>Staff</option><option>Manager</option></select></td>'+
        '<td><select class="editable ns-mgr" style="min-width:150px;">'+mgrOpts+'</select></td>'+
        '<td><input class="editable mono ns-gross" type="number" min="0" style="width:100px;"></td>'+
        '<td><input class="editable mono ns-doj" type="date"></td>'+
        '<td><input class="editable mono ns-cl" type="number" min="0" step="0.5" style="width:60px;" value="'+DEFAULT_MONTHLY_CL+'"></td>'+
        '<td><input class="editable mono ns-perm" type="number" min="0" step="0.5" style="width:60px;" value="'+(DEFAULT_MONTHLY_PERMISSION_MIN/60)+'"></td>'+
      '</tr>';
    }).join('')+
    '</tbody></table></div>';
  }
  function wireNewStaffPanel(parsed){
    const btn = document.getElementById('attImportCommitBtn');
    const rows = ()=> Array.from(document.querySelectorAll('#attImportPreview .ns-row'));
    const label = ()=>{
      const add = rows().filter(r=>r.querySelector('.ns-inc').checked);
      const addSet = new Set(add.map(r=>r.dataset.code));
      const n = parsed.records.filter(r=>findStaff(r.empNo) || addSet.has(r.empNo)).length;
      btn.textContent = 'Import '+n+' record(s)'+(add.length ? ' + add '+add.length+' new staff' : '');
      btn.disabled = n===0;
    };
    const cls = {unit:'.ns-unit', dept:'.ns-dept', desg:'.ns-desg', shift:'.ns-shift', mgr:'.ns-mgr', doj:'.ns-doj', cl:'.ns-cl', perm:'.ns-perm'};
    document.querySelectorAll('#attImportPreview .ns-all').forEach(el=> el.onchange = ()=>{
      if(el.value==='' && el.tagName==='SELECT' && el.dataset.f!=='mgr') return;
      rows().forEach(r=>{ const t = r.querySelector(cls[el.dataset.f]); if(t) t.value = el.value; });
    });
    rows().forEach(r=>{
      r.querySelector('.ns-inc').onchange = label;
      r.querySelectorAll('input,select').forEach(field=> field.addEventListener('change', ()=>{
        r.style.outline = '';
        field.style.borderColor = '';
      }));
    });
    label();
    btn.onclick = ()=>{
      const err = document.getElementById('attImportError');
      const add = rows().filter(r=>r.querySelector('.ns-inc').checked);
      const v = (r, c)=> (r.querySelector(c) ? r.querySelector(c).value.trim() : '');
      const importedName = r=> cleanImportedName(v(r,'.ns-name') || parsed.names[r.dataset.code], r.dataset.code);
      const required = [
        {label:'Name', selector:'.ns-name', missing:r=>!importedName(r)},
        {label:'Unit', selector:'.ns-unit', missing:r=>!v(r,'.ns-unit')},
        {label:'Department', selector:'.ns-dept', missing:r=>!v(r,'.ns-dept')},
        {label:'Designation', selector:'.ns-desg', missing:r=>!v(r,'.ns-desg')},
        {label:'Shift', selector:'.ns-shift', missing:r=>!v(r,'.ns-shift')},
        {label:'Gross salary', selector:'.ns-gross', missing:r=>!(parseFloat(v(r,'.ns-gross'))>0)},
      ];
      rows().forEach(r=>{
        r.style.outline = '';
        required.forEach(f=>{ const field=r.querySelector(f.selector); if(field) field.style.borderColor=''; });
      });
      const invalid = add.map(r=>({r, missing:required.filter(f=>f.missing(r))})).filter(x=>x.missing.length);
      if(invalid.length){
        invalid.forEach(x=>{
          x.r.style.outline = '2px solid var(--rose)';
          x.missing.forEach(f=>{ const field=x.r.querySelector(f.selector); if(field) field.style.borderColor='var(--rose)'; });
        });
        const details = invalid.slice(0,8).map(x=>x.r.dataset.code+': '+x.missing.map(f=>f.label).join(', ')).join(' · ');
        err.textContent = 'Complete the highlighted fields — '+details+(invalid.length>8?' · +'+(invalid.length-8)+' more':'')+'. You can untick staff who should not be added.';
        return;
      }
      err.textContent = '';
      const today = todayISO();
      add.forEach(r=>{
        const code = r.dataset.code;
        if(findStaff(code)) return;
        const unitCode = v(r,'.ns-unit'), gross = parseFloat(v(r,'.ns-gross'))||0;
        STAFF.push({
          dbRef: nextStaffRef(), empNo: code, name: importedName(r), role: v(r,'.ns-role') || 'Staff',
          reportingManager: v(r,'.ns-mgr'), designation: v(r,'.ns-desg'), department: v(r,'.ns-dept'), unitCode,
          shiftCode: v(r,'.ns-shift'), netSalary: gross,
          monthlyCL: v(r,'.ns-cl')==='' ? DEFAULT_MONTHLY_CL : (parseFloat(v(r,'.ns-cl'))||0),
          monthlyPermissionHours: v(r,'.ns-perm')==='' ? DEFAULT_MONTHLY_PERMISSION_MIN/60 : (parseFloat(v(r,'.ns-perm'))||0),
          phone: '', email: '', doj: v(r,'.ns-doj'), dob: '', address: '', otEligible: false, pfApplicable: true,
          esiApplicable: gross<=PAYROLL_SETTINGS.esi.ceiling, otherDeduction: 0,
          username: code, password: code, active: true,
          unitHistory: [{unitCode, effectiveFrom: today, note: 'Added from attendance import'}],
        });
        if(!ATTENDANCE[code]) ATTENDANCE[code] = {primaryShift: v(r,'.ns-shift') || null, records: []};
      });
      const records = parsed.records.filter(r=>findStaff(r.empNo));
      if(add.length) alert(add.length+' new staff added to Staff Master. Their first password is their Staff Code — use "Create missing logins" in Staff Master to give them sign-in accounts.');
      commitAttendanceImport(records);
    };
  }
  function commitAttendanceImport(records){
    let added=0, updated=0;
    records.forEach(r=>{
      if(!ATTENDANCE[r.empNo]) ATTENDANCE[r.empNo] = {primaryShift:null, records:[]};
      const list = ATTENDANCE[r.empNo].records;
      const existing = list.find(x=>x.date===r.date);
      if(existing){
        existing.status = r.status;
        if(r.in) existing.in = r.in; else delete existing.in;
        if(r.out) existing.out = r.out; else delete existing.out;
        updated++;
      } else {
        const rec = {date:r.date, status:r.status};
        if(r.in) rec.in = r.in;
        if(r.out) rec.out = r.out;
        list.push(rec);
        added++;
      }
      list.sort((a,b)=>a.date.localeCompare(b.date));
    });
    document.getElementById('modalRoot').innerHTML = '';
    alert('Import complete: '+added+' new record(s) added, '+updated+' existing record(s) updated.');
    renderAdminLedger();
    env.afterImport();
  }

