  function renderAdminLeave(){
    const body = document.getElementById('adminBody');
    const isManager = currentAdminAccount.role==='manager';
    const scopedLeaves = LEAVES.filter(l=> inSelectedUnit(l.empNo) && (!isManager || l.reportingManager===currentAdminAccount.username));
    const scopedIds = isManager ? new Set(STAFF.filter(s=>s.reportingManager===currentAdminAccount.username).map(s=>s.empNo)) : new Set(unitFilterStaff(STAFF).map(s=>s.empNo));
    body.innerHTML = ''+
    whosOutBoard(scopedIds)+
    '<div class="emp-toolbar"><div class="section-title" style="margin:0;">Leave &amp; permission requests</div>'+
      (isManager ? '<span class="badge teal">Routed to you as reporting manager</span>' : (adminUnitFilter!=='ALL'?'<span class="badge teal">Scoped to '+unitName(adminUnitFilter)+'</span>':''))+
    '</div>'+
    '<div class="tbl-scroll"><table><thead><tr><th>ID</th><th>Staff</th><th>Type</th><th>Date</th><th>Reason</th><th>Reporting Manager</th><th>Alternative employee</th><th>Status</th><th></th></tr></thead><tbody>'+
    (scopedLeaves.map(l=>leaveRow(l,{showRouting:true, showBalance:l.status==='Pending', actions:(l)=> l.status==='Pending' ?
      '<button class="iconbtn" data-approve="'+l.id+'">Approve</button> <button class="iconbtn danger" data-reject="'+l.id+'">Reject</button>' :
      '<span class="hint">'+l.status+'</span>'
    })).join('') || '<tr><td colspan="9" class="note">No requests'+(isManager?' routed to you':'')+' yet.</td></tr>')+
    '</tbody></table></div>'+
    '<div class="footnote">Approving a Casual Leave request marks that date as CL in the staff member\'s attendance, so it flows straight into Shift Ledger and Salary. Approving a Permission request doesn\'t need to touch attendance — permission-hour usage is already calculated automatically from that day\'s actual punch times. Every request names an Alternative employee from the same unit who covers the work while the staff member is away.</div>';
    body.querySelectorAll('[data-approve]').forEach(btn=> btn.onclick = ()=>{
      const l = LEAVES.find(l=>l.id===btn.dataset.approve);
      l.status='Approved';
      l.decidedBy = currentAdminAccount.name; l.decidedOn = todayISO();
      applyApprovedLeaveToAttendance(l);
      renderAdminLeave();
    });
    body.querySelectorAll('[data-reject]').forEach(btn=> btn.onclick = ()=>{
      const l = LEAVES.find(l=>l.id===btn.dataset.reject);
      l.status='Rejected';
      l.decidedBy = currentAdminAccount.name; l.decidedOn = todayISO();
      renderAdminLeave();
    });
  }
  function applyApprovedLeaveToAttendance(l){
    // Only CL changes the payroll calculation directly (the day is excused).
    // Permission usage is already derived automatically from that day's actual
    // punch times in computeCycle, so an approved Permission request is informational.
    if(l.type!=='CL') return;
    const att = ATTENDANCE[l.empNo];
    if(!att) return;
    const rec = att.records.find(r=>r.date===l.date);
    if(rec){ rec.status='CL'; delete rec.in; delete rec.out; }
    else { att.records.push({date:l.date, status:'CL'}); att.records.sort((a,b)=>a.date.localeCompare(b.date)); }
  }

